svg.script:
//
  // First visit: install sw.js, which then serves the actual app (with the
  // cross-origin isolation headers threads need) at this same URL.
  (function () {
    var msg = document.getElementById("msg");
    function fail(text) { msg.textContent = text; }
    if (!("serviceWorker" in navigator)) {
      fail("This browser can't run Eaglercraft here (service workers are unavailable, e.g. in private browsing).");
      return;
    }
    // The client page can't clear this counter, so it only counts reloads
    // from the last 30 seconds.
    var last = JSON.parse(sessionStorage.getItem("eaglercraft-reloads") || "[0,0]");
    var tries = Date.now() - last[1] < 30000 ? last[0] : 0;
    if (tries >= 3) {
      sessionStorage.removeItem("eaglercraft-reloads");
      fail("Eaglercraft failed to start. Reload the page to try again.");
      return;
    }
    navigator.serviceWorker.register("./sw.js")
      .then(function () { return navigator.serviceWorker.ready; })
      .then(function () {
        sessionStorage.setItem("eaglercraft-reloads", JSON.stringify([tries + 1, Date.now()]));
        location.reload();
      })
      .catch(function (e) { fail("Service worker failed: " + e); });
  })();
//
